 *
 * LmmMapTest — round-trip: load a real .lmm generated by
 * scripts/make_lmm_map.py, query a bbox around a Berlin crossing,
 * verify the roads a navigation display would need, and render a PNG
 * preview (same palette as MapProjectorTest).
 *
 * The .lmm fixture is generated on the fly by the test setup? No — the
 * file is produced by the script and committed as a test resource
 * (src/test/resources/test.lmm). If missing, the test regenerates a
 * synthetic map in memory instead (no network in unit tests).
 */
package de.jacksitlab.libremoto.bridge

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.ByteArrayInputStream
import java.io.File
import java.io.FileOutputStream
import java.util.zip.CRC32

class LmmMapTest {

    /** Build a synthetic .lmm in memory — same writer as the Python script. */
    private fun synthLmm(roads: List<Pair<String, List<Pair<Double, Double>>>>): ByteArray {
        val types = listOf(
            "motorway", "motorway_link", "trunk", "trunk_link",
            "primary", "primary_link", "secondary", "secondary_link",
            "tertiary", "tertiary_link", "residential", "unclassified",
            "living_street", "service", "road",
        )
        val typeIdx = types.withIndex().associate { (i, t) -> t to i }

        fun tileX(lon: Double): Int {
            val n = 1 shl LmmMap.ZOOM
            return ((lon + 180.0) / 360.0 * n).toInt().coerceIn(0, n - 1)
        }

        fun tileY(lat: Double): Int {
            val n = 1 shl LmmMap.ZOOM
            val rad = Math.toRadians(lat.coerceIn(-85.05, 85.05))
            val y = (1.0 - Math.log(Math.tan(rad) + 1.0 / Math.cos(rad)) / Math.PI) / 2.0
            return (y * n).toInt().coerceIn(0, n - 1)
        }

        // road table
        val roadBlob = java.io.ByteArrayOutputStream()
        roads.forEach { (hw, pts) ->
            roadBlob.write(typeIdx[hw]!!)
            roadBlob.write(pts.size)
            pts.forEach { (lat, lon) ->
                val l = java.nio.ByteBuffer.allocate(8)
                    .order(java.nio.ByteOrder.LITTLE_ENDIAN)
                    .putInt((lat * 1e7).toInt()).putInt((lon * 1e7).toInt()).array()
                roadBlob.write(l)
            }
        }

        // tile index
        val tileRoads = HashMap<Pair<Int, Int>, MutableList<Int>>()
        roads.forEachIndexed { ri, (_hw, pts) ->
            val tx0 = tileX(pts.minOf { it.second }); val tx1 = tileX(pts.maxOf { it.second })
            val ty0 = tileY(pts.maxOf { it.first }); val ty1 = tileY(pts.minOf { it.first })
            for (ty in ty0..ty1) for (tx in tx0..tx1)
                tileRoads.getOrPut(tx to ty) { mutableListOf() }.add(ri)
        }
        val tiles = tileRoads.entries.sortedWith(compareBy({ it.key.first }, { it.key.second }))
        val header = java.io.ByteArrayOutputStream()
        fun u32(v: Int) { header.write(v and 0xFF); header.write((v shr 8) and 0xFF); header.write((v shr 16) and 0xFF); header.write((v shr 24) and 0xFF) }
        header.write("LMM1".toByteArray())
        u32(tiles.size); u32(roads.size)
        tiles.forEach { (k, rl) -> u32(k.first); u32(k.second); u32(rl.first()); u32(rl.last() + 1) }

        return header.toByteArray() + roadBlob.toByteArray()
    }

    @Test
    fun loadQueryAndRender() {
        // synthetic crossing: route street + parallel + cross + far motorway
        val centerLat = 52.52; val centerLon = 13.405
        fun at(northM: Double, eastM: Double) =
            (centerLat + northM / 111_320.0) to
            (centerLon + eastM / (111_320.0 * kotlin.math.cos(Math.toRadians(centerLat))))
        val roads = listOf(
            "residential" to listOf(at(0.0, 0.0), at(200.0, 0.0), at(400.0, 0.0)),
            "residential" to listOf(at(-100.0, 120.0), at(100.0, 120.0), at(300.0, 120.0)),
            "secondary" to listOf(at(200.0, -300.0), at(200.0, 0.0), at(200.0, 300.0)),
            "service" to listOf(at(80.0, 0.0), at(80.0, 150.0)),
            "motorway" to listOf(at(900.0, 500.0), at(1200.0, 700.0)),  // outside query
        )
        val lmm = LmmMap.load(ByteArrayInputStream(synthLmm(roads)))
        assertEquals(5, lmm.roadCount)

        // query: ±400 m around the vehicle
        val dLat = 400.0 / 111_320.0
        val dLon = 400.0 / (111_320.0 * kotlin.math.cos(Math.toRadians(centerLat)))
        val found = lmm.queryBbox(centerLat - dLat, centerLon - dLon,
                                   centerLat + dLat, centerLon + dLon)
        println("queryBbox ±400 m: ${found.size} roads: ${found.map { it.highway }}")
        assertTrue("at least 4 roads expected", found.size >= 4)
        assertTrue("motorway excluded", found.none { it.highway == "motorway" })
        assertTrue("cross street included", found.any { it.highway == "secondary" })

        // also load the committed fixture if present (real Overpass data)
        val fixture = File("src/test/resources/test.lmm")
        if (fixture.exists()) {
            val real = LmmMap.load(fixture.inputStream())
            val rf = real.queryBbox(centerLat - dLat, centerLon - dLon,
                                    centerLat + dLat, centerLon + dLon)
            println("fixture: ${real.roadCount} roads total, query: ${rf.size}")
            assertTrue(rf.isNotEmpty())
            renderPng(File("build/map-preview/lmm-query.png"), centerLat, centerLon, rf)
        } else {
            renderPng(File("build/map-preview/lmm-query.png"), centerLat, centerLon, found)
        }
        println("PNG: ${File("build/map-preview/lmm-query.png").absolutePath}")
    }

    // ---- PNG writer (same minimal writer as MapProjectorTest) -------------
    private fun renderPng(file: File, centerLat: Double, centerLon: Double,
                          roads: List<LmmRoad>) {
        val W = 480; val H = 480
        val img = Array(H) { IntArray(W) { 0x0D1117 } }
        val scale100 = 48   // city zoom
        val pxPerM = scale100 / 100.0

        fun plot(x: Int, y: Int, c: Int) { if (x in 0 until W && y in 0 until H) img[y][x] = c }
        fun line(x0: Int, y0: Int, x1: Int, y1: Int, w: Int, c: Int) {
            val steps = maxOf(kotlin.math.abs(x1 - x0), kotlin.math.abs(y1 - y0)) * 2 + 1
            for (s in 0..steps) {
                val t = s.toDouble() / steps
                val x = (x0 + (x1 - x0) * t).toInt(); val y = (y0 + (y1 - y0) * t).toInt()
                val r = w / 2
                for (dy in -r..r) for (dx in -r..r)
                    if (dx * dx + dy * dy <= r * r) plot(x + dx, y + dy, c)
            }
        }

        for (road in roads) {
            val pts = (0 until road.npts).map { i ->
                val lat = road.latE7[i] / 1e7
                val lon = road.lonE7[i] / 1e7
                val north = (lat - centerLat) * 111_320.0
                val east = (lon - centerLon) * 111_320.0 * kotlin.math.cos(Math.toRadians(centerLat))
                (240 + east * pxPerM).toInt() to (240 - north * pxPerM).toInt()
            }
            val width = MapProjector.roadWidthPx(road.highway, scale100)
            for (i in 0 until pts.size - 1)
                line(pts[i].first, pts[i].second, pts[i + 1].first, pts[i + 1].second, width, 0xE6EDF3)
        }
        for (dy in -6..6) for (dx in -6..6)
            if (dx * dx + dy * dy <= 36) plot(240 + dx, 240 + dy, 0x3FB950)

        writePng(file, W, H, img)
    }

    private fun writePng(file: File, w: Int, h: Int, rgb: Array<IntArray>) {
        fun chunk(type: String, data: ByteArray): ByteArray {
            val out = ByteArray(12 + data.size)
            val len = data.size
            out[0] = ((len shr 24) and 0xFF).toByte(); out[1] = ((len shr 16) and 0xFF).toByte()
            out[2] = ((len shr 8) and 0xFF).toByte(); out[3] = (len and 0xFF).toByte()
            for (i in 0 until 4) out[4 + i] = type[i].code.toByte()
            System.arraycopy(data, 0, out, 8, data.size)
            val crc = CRC32(); crc.update(type.toByteArray()); crc.update(data)
            val v = crc.value.toInt()
            out[8 + data.size] = ((v shr 24) and 0xFF).toByte()
            out[9 + data.size] = ((v shr 16) and 0xFF).toByte()
            out[10 + data.size] = ((v shr 8) and 0xFF).toByte()
            out[11 + data.size] = (v and 0xFF).toByte()
            return out
        }
        val sig = byteArrayOf(0x89.toByte(), 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A)
        val ihdr = ByteArray(13)
        ihdr[0] = ((w shr 24) and 0xFF).toByte(); ihdr[1] = ((w shr 16) and 0xFF).toByte()
        ihdr[2] = ((w shr 8) and 0xFF).toByte(); ihdr[3] = (w and 0xFF).toByte()
        ihdr[4] = ((h shr 24) and 0xFF).toByte(); ihdr[5] = ((h shr 16) and 0xFF).toByte()
        ihdr[6] = ((h shr 8) and 0xFF).toByte(); ihdr[7] = (h and 0xFF).toByte()
        ihdr[8] = 8.toByte(); ihdr[9] = 2.toByte()
        val raw = ByteArray(h * (1 + w * 3))
        var o = 0
        for (y in 0 until h) {
            raw[o++] = 0
            for (x in 0 until w) {
                val c = rgb[y][x]
                raw[o++] = ((c shr 16) and 0xFF).toByte()
                raw[o++] = ((c shr 8) and 0xFF).toByte()
                raw[o++] = (c and 0xFF).toByte()
            }
        }
        val def = java.util.zip.Deflater(java.util.zip.Deflater.BEST_COMPRESSION)
        def.setInput(raw); def.finish()
        val idat = ByteArray(raw.size); val n = def.deflate(idat); def.end()
        val png = sig + chunk("IHDR", ihdr) + chunk("IDAT", idat.copyOf(n)) + chunk("IEND", ByteArray(0))
        FileOutputStream(file).use { it.write(png) }
    }
}
